//! `pkinit_cert_match`: the rules select the identity before it is used (MIT
//! 1.22.2 `pkinit_matching.c`, plan 2 todo 28, MIT-config-51).
//!
//! The identities are `tests/pkinit/fixtures/match/*.pem`, generated by the
//! OpenSSL CLI (`generate.sh` there); the expected renderings are what
//! `openssl x509 -nameopt sep_comma_plus` prints, MIT's flags.

use core::{error::Error, fmt::Write as _};
use std::{fs, path::PathBuf};

use rskrb5_ng::{
    Config,
    client::principal::Principal,
    error::Pkinit,
    preauth::pkinit::{ConfiguredIdentities, Identity, IdentityProvider as _, KdcTrust, matching::CertificateRules},
};

/// A boxed test failure.
pub(crate) type TestError = Box<dyn Error>;

/// The realm.
pub(crate) const REALM: &str = "TEST.RSKRB5";

/// The fixture directory.
pub(crate) fn dir() -> PathBuf {
    PathBuf::from(format!(
        "{}/tests/pkinit/fixtures/match",
        env!("CARGO_MANIFEST_DIR")
    ))
}

/// A profile with the fixture `identities` and the `rules`, one relation line each.
pub(crate) fn config(identities: &[&str], rules: &[&str]) -> Result<Config, TestError> {
    let mut lines = String::new();
    for name in identities {
        let base = dir().join(name).display().to_string();
        writeln!(lines, " pkinit_identities = FILE:{base}.pem,{base}.key")?;
    }
    for rule in rules {
        writeln!(lines, " pkinit_cert_match = {rule}")?;
    }
    Ok(Config::parse(&format!(
        "[libdefaults]\n default_realm = {REALM}\n[realms]\n {REALM} = {{\n kdc = 127.0.0.1:1\n{lines} }}\n"
    ))?)
}

/// The DER certificate of the fixture `name`.
fn certificate(name: &str) -> Result<Vec<u8>, TestError> {
    let base = dir().join(name).display().to_string();
    let identity = Identity::from_files(
        format!("{base}.pem").as_ref(),
        Some(format!("{base}.key").as_ref()),
    )?;
    Ok(identity.certificate().to_vec())
}

/// What `identities` and `rules` select: the fixture name, or the typed error.
pub(crate) fn select(identities: &[&str], rules: &[&str]) -> Result<String, Pkinit> {
    let profile = config(identities, rules).map_err(|_unparsed| Pkinit::Identity {
        reason: "the test profile did not parse",
    })?;
    let provider = ConfiguredIdentities::from_config(&profile, REALM)?;
    let chosen = provider
        .identity(&Principal::user(REALM, "user"))
        .map_err(|error| match error.downcast::<Pkinit>() {
            Ok(typed) => *typed,
            Err(_other) => Pkinit::Identity {
                reason: "a provider error that is not a Pkinit error",
            },
        })?;
    for name in identities {
        if certificate(name).is_ok_and(|der| der == chosen.certificate()) {
            return Ok((*name).to_owned());
        }
    }
    Err(Pkinit::Identity {
        reason: "the selected certificate is no fixture",
    })
}

/// Every fixture identity.
const ALL: [&str; 10] = [
    "user", "generic", "alice", "bob", "carol", "doe", "erin", "frank", "gina", "henry",
];

/// The DER certificate of the fixture `name`, whatever its key.
fn der_of(name: &str) -> Result<Vec<u8>, TestError> {
    let pem = fs::read(dir().join(format!("{name}.pem")))?;
    KdcTrust::from_pem(&pem)?
        .anchors()
        .first()
        .cloned()
        .ok_or_else(|| "no certificate".into())
}

/// A single rule selects the identity it matches, over every component kind.
#[test]
fn certificate_rules_select_the_matching_identity() -> Result<(), TestError> {
    // Given the eight identities, when one rule is configured, then exactly the
    // identity it matches is chosen (never the first loadable one).
    let pool = ["alice", "bob", "carol", "doe", "erin", "frank", "user"];
    for (rule, expected) in [
        ("<SUBJECT>CN=bob$", "bob"),
        ("<SUBJECT>^O=OTHER.COM,", "carol"),
        ("<ISSUER>O=OTHER CA", "carol"),
        ("<ISSUER>^O=DoE CA,", "doe"),
        ("<SAN>^alice@TEST.RSKRB5$", "alice"),
        ("<SAN>^alice@upn.test$", "alice"),
        ("<SAN>^user@KRBTEST.COM$", "user"),
        ("<SAN>^user\\@KRBTEST\\.COM$", "user"),
        ("<SAN>^[[:alpha:]]+@KRBTEST[.]COM$", "user"),
        ("<EKU>msScLogin<KU>digitalSignature", "doe"),
        ("<KU>keyEncipherment,<SAN>^alice@TEST", "alice"),
        ("<EKU>emailProtection", "bob"),
        ("<EKU>pkinit,msScLogin", "never-matches"),
        ("<KU>keyEncipherment<EKU>pkinit<SAN>alice", "alice"),
        ("<KU>keyEncipherment<SUBJECT>CN=\\\\U4E2D", "erin"),
        ("&&<SUBJECT>O=OTHER.COM<EKU>msScLogin", "carol"),
        ("||<SUBJECT>CN=carol$<SAN>^nobody@", "carol"),
        ("<SAN>^frank/admin@TEST.RSKRB5$", "frank"),
        ("<SAN>^fr\\\\@nk@TEST.RSKRB5$", "frank"),
    ] {
        let result = select(&pool, &[rule]);
        if expected == "never-matches" {
            assert!(
                matches!(result, Err(Pkinit::NoMatchingCertificate { candidates: 7 })),
                "{rule}: {result:?}"
            );
        } else {
            assert_eq!(
                result.map_err(|error| format!("{rule}: {error:?}"))?,
                expected,
                "{rule}"
            );
        }
    }
    Ok(())
}

/// The first rule that selects exactly one identity wins; a rule that matches
/// several or none passes the decision to the next (MIT `pkinit_matching.c:643-696`).
#[test]
fn certificate_rule_order_follows_mit() -> Result<(), TestError> {
    let pool = ["alice", "bob", "carol"];
    // Given a first rule matching two identities, then the second unique rule decides.
    assert_eq!(
        select(&pool, &["<SUBJECT>O=KRBTEST.COM", "<SUBJECT>CN=carol$"])?,
        "carol"
    );
    // Given two unique rules, then the first wins whatever the second selects.
    assert_eq!(
        select(&pool, &["<SUBJECT>CN=bob$", "<SUBJECT>CN=alice$"])?,
        "bob"
    );
    // Given a first rule matching nothing, then the second decides.
    assert_eq!(
        select(&pool, &["<SUBJECT>CN=nobody", "<SUBJECT>CN=alice$"])?,
        "alice"
    );
    Ok(())
}

/// More than one match never picks the first; no match is its own typed error.
#[test]
fn certificate_rule_ambiguity_fails_closed() {
    let pool = ["alice", "bob", "carol"];
    // Given a rule that two identities satisfy, then the selection is refused.
    let ambiguous = select(&pool, &["<SUBJECT>O=KRBTEST.COM"]);
    assert!(
        matches!(ambiguous, Err(Pkinit::AmbiguousCertificates { candidates: 3 })),
        "{ambiguous:?}"
    );
    // And an `||` rule that matches every identity through different components.
    let either = select(&pool, &["||<SUBJECT>CN=carol$<EKU>clientAuth"]);
    assert!(
        matches!(either, Err(Pkinit::AmbiguousCertificates { candidates: 3 })),
        "{either:?}"
    );
    // And several rules that never select exactly one: ambiguity wins over "no match".
    let none = select(&pool, &["<SUBJECT>O=KRBTEST.COM", "<SUBJECT>CN=nobody"]);
    assert!(
        matches!(none, Err(Pkinit::AmbiguousCertificates { candidates: 3 })),
        "{none:?}"
    );
    // And a rule that matches nothing is NoMatchingCertificate, not the first identity.
    let nothing = select(&pool, &["<SUBJECT>CN=nobody"]);
    assert!(
        matches!(nothing, Err(Pkinit::NoMatchingCertificate { candidates: 3 })),
        "{nothing:?}"
    );
}

/// Without rules exactly one identity must be configured (MIT
/// `crypto_cert_select_default`, `pkinit_crypto_openssl.c:4986`).
#[test]
fn identities_without_rules_must_be_exactly_one() -> Result<(), TestError> {
    assert_eq!(select(&["bob"], &[])?, "bob");
    let two = select(&["alice", "bob"], &[]);
    assert!(
        matches!(two, Err(Pkinit::AmbiguousCertificates { candidates: 2 })),
        "{two:?}"
    );
    let none = select(&[], &["<SUBJECT>CN=bob"]);
    assert!(
        matches!(none, Err(Pkinit::NoMatchingCertificate { candidates: 0 })),
        "{none:?}"
    );
    Ok(())
}

/// The DN renderings are OpenSSL's `XN_FLAG_SEP_COMMA_PLUS`.
///
/// MIT `rfc2253_name`: a rule that is the escaped expected text, anchored,
/// selects its identity. `erin` has a multi-valued RDN, a comma, a plus and
/// UTF-8 above U+0100; `gina` has a `BMPString` holding U+00FC (one
/// character) and U+4E2D.
#[test]
fn certificate_names_render_like_mit_openssl() -> Result<(), TestError> {
    // The table holds OpenSSL's raw bytes (a Latin-1 character is one byte).
    let table: String = fs::read(dir().join("subjects.tsv"))?
        .into_iter()
        .map(char::from)
        .collect();
    let escape = |text: &str| {
        let mut out = String::new();
        for character in text.chars() {
            if ".[]()*+?{}|^$\\-/@".contains(character) {
                out.push('\\');
            }
            out.push(character);
        }
        out
    };
    for line in table.lines() {
        let mut columns = line.split('\t');
        let (name, subject, issuer) = (
            columns.next().ok_or("name")?,
            columns.next().ok_or("subject")?,
            columns.next().ok_or("issuer")?,
        );
        let ders = ALL.iter().map(|other| der_of(other)).collect::<Result<Vec<_>, _>>()?;
        let views: Vec<&[u8]> = ders.iter().map(Vec::as_slice).collect();
        let index = ALL.iter().position(|other| *other == name).ok_or("fixture")?;
        let by_subject = format!("<SUBJECT>^{}$", escape(subject));
        let by_issuer_and_subject = format!(
            "<ISSUER>^{}$<SUBJECT>^{}$",
            escape(issuer),
            escape(subject)
        );
        // The generic and the user fixtures share a subject: the rule cannot
        // tell them apart, which is the ambiguity rule.
        let expected = if name == "user" || name == "generic" { None } else { Some(index) };
        for rule in [&by_subject, &by_issuer_and_subject] {
            let rules = CertificateRules::parse(&[rule.as_str()])?;
            match (rules.select(&views), expected) {
                (Ok(chosen), Some(wanted)) => assert_eq!(chosen, wanted, "{rule}"),
                (Err(Pkinit::AmbiguousCertificates { candidates: 10 }), None) => {}
                (other, _) => return Err(format!("{name}: {rule}: {other:?}").into()),
            }
        }
    }
    Ok(())
}

/// The rule examples of MIT's own test suite (`src/tests/t_pkinit.py:337-390`)
/// and of `krb5.conf(5)`, over the fixtures built to match their identities.
#[test]
fn certificate_rules_match_mit_fixtures() -> Result<(), TestError> {
    // t_pkinit.py: `p12_identity` is O=KRBTEST.COM,CN=user with SAN
    // user@KRBTEST.COM, KU digitalSignature + keyEncipherment; `p12_generic_identity`
    // is the same subject and an issuer O=MIT with no PKINIT extensions.
    for (rule, passes) in [
        ("<SAN>^user@KRBTEST.COM$", true),
        ("<SAN>^user@krbtest.com$", false),
        ("<SUBJECT>CN=user$<KU>digitalSignature,keyEncipherment", true),
        ("&&<SUBJECT>O=OTHER.COM<SAN>^user@KRBTEST.COM$", false),
        ("||<SUBJECT>O=KRBTEST.COM<SAN>^otheruser@KRBTEST.COM$", true),
        ("||<SUBJECT>O=OTHER.COM<SAN>^otheruser@KRBTEST.COM$", false),
        ("&&<SUBJECT>CN=user$<ISSUER>O=MIT,", true),
    ] {
        let result = select(&["user"], &[rule]);
        if passes {
            assert_eq!(result?, "user", "{rule}");
        } else {
            assert!(
                matches!(result, Err(Pkinit::NoMatchingCertificate { candidates: 1 })),
                "{rule}: {result:?}"
            );
        }
    }
    // The generic certificate has no PKINIT SAN: only its subject and issuer match.
    assert_eq!(
        select(&["generic"], &["&&<SUBJECT>CN=user$<ISSUER>O=MIT,"])?,
        "generic"
    );
    let generic_san = select(&["generic"], &["<SAN>^user@KRBTEST.COM$"]);
    assert!(
        matches!(generic_san, Err(Pkinit::NoMatchingCertificate { candidates: 1 })),
        "{generic_san:?}"
    );
    // krb5.conf(5) examples, on John DoE (issuer O=DoE CA, SAN john@EXAMPLE.COM,
    // EKU msScLogin + clientAuth, KU digitalSignature) beside identities they must reject.
    let pool = ["doe", "carol", "alice"];
    for rule in [
        "||<SUBJECT>.*DoE.*<SAN>.*@EXAMPLE.COM",
        "&&<EKU>msScLogin,clientAuth<ISSUER>.*DoE.*",
        "<EKU>msScLogin,clientAuth<KU>digitalSignature",
    ] {
        assert_eq!(select(&pool, &[rule])?, "doe", "{rule}");
    }
    Ok(())
}

/// A dNSName SAN is not matched (MIT matches only the PKINIT SANs and the UPNs).
#[test]
fn certificate_rules_ignore_dns_names() {
    let none = select(&["alice", "bob"], &["<SAN>alice\\.example\\.test"]);
    assert!(
        matches!(none, Err(Pkinit::NoMatchingCertificate { candidates: 2 })),
        "{none:?}"
    );
}
